import type { ContentBlockManifestEntry } from './contentBlocks.js'

// Hand-authored, NOT generated by scripts/scanVariables.mjs — unlike
// contentBlocks.generated.ts, these keys back Cover Page component PROPS
// (title/subtitle/description/tags/clientName/preparedBy), not literal JSX
// text, so the scanner structurally can't see them (it only records elements
// whose children are pure JsxText). Shaped identically to
// ContentBlockManifestEntry so the Editor's existing click-to-edit /
// contentOverride / undo / autosave pipeline needs zero changes to support
// them — see ProposalEditor.tsx, which concatenates these onto the
// generated cover entries.

const DEFAULT_DESCRIPTION =
  'Built for [Client Name]. Most founders are not short on leads. They are losing revenue between the lead and the close, and they do not know where. This proposal finds the leak and fixes it.'

/** Minimal proposal metadata needed to seed the auto-resolved defaults (Client Name / Prepared By). */
export interface CoverFieldSource {
  clientName?: string
  preparedBy?: string
}

/**
 * Returns every Cover Page prop-backed field as a content-block-shaped
 * entry. `clientName`/`preparedBy` default to the proposal's own metadata
 * (falling back to the template's original placeholder text only if that
 * metadata is empty) — this is what makes "Client Name = John Smith"
 * resolve on the canvas automatically, with no manual replacement, for both
 * brand-new and pre-existing documents (no DB migration needed: an
 * explicit contentOverride, once saved, still wins over this default the
 * same way it does for every other content block).
 */
export function getCoverFieldEntries(source: CoverFieldSource): ContentBlockManifestEntry[] {
  return [
    { key: 'cover.title', page: 'cover', originalText: 'RevOps', label: 'Proposal Title', variants: ['both'] },
    { key: 'cover.heading', page: 'cover', originalText: 'Proposal', label: 'Main Heading', variants: ['both'] },
    { key: 'cover.paragraph', page: 'cover', originalText: DEFAULT_DESCRIPTION, label: 'Main Paragraph', variants: ['both'] },
    { key: 'cover.tag0', page: 'cover', originalText: 'Diagnose', label: 'Floating Tag — Diagnose', variants: ['both'] },
    { key: 'cover.tag1', page: 'cover', originalText: 'Fix', label: 'Floating Tag — Fix', variants: ['both'] },
    { key: 'cover.tag2', page: 'cover', originalText: 'Automate', label: 'Floating Tag — Automate', variants: ['both'] },
    { key: 'cover.tag3', page: 'cover', originalText: 'Convert', label: 'Floating Tag — Convert', variants: ['both'] },
    { key: 'cover.tag4', page: 'cover', originalText: 'Scale', label: 'Floating Tag — Scale', variants: ['both'] },
    {
      key: 'cover.clientName',
      page: 'cover',
      originalText: source.clientName?.trim() || '[Client Name]',
      label: 'Client Name',
      variants: ['both'],
    },
    {
      key: 'cover.preparedBy',
      page: 'cover',
      originalText: source.preparedBy?.trim() || 'Jayson Kandiah',
      label: 'Prepared By',
      variants: ['both'],
    },
  ]
}
